VALUES ('neial-005', 'NEIAL-005', 'LanguageCanBeFormalized', 'Premise', 'Witness', 'There exists at least one clear witness that satisfies the operational definition: Python.', '∃x (x=Python ∧ Language(x))', 'Python', 'python', 'HasSyntax=True; RequiresParsing=True; HasLinearDecodingPressure=True; IsOngologyDescriptor=True; CanBeHeld=False; HasIdentity=False; DistanceFromConcept=2; Category=Formal Language', 'If any predicate is false in your current dataset for this witness, adjust the candidate record or relax the definition.') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

INSERT INTO is_everything_a_language (is_everything_a_language_id, name, argument_name, argument_category, step_type, statement, formalization, related_candidate_name, related_candidate_id, evidence_from_rulebook, notes)
VALUES ('neial-006', 'NEIAL-006', 'LanguageCanBeFormalized', 'Conclusion', 'Conclusion', 'Therefore, ''language'' can be formalized as a computable classification boundary over explicit predicates.', '(Definition ∧ Witnesses) ⇒ Formalizable(Language)', '', '', '', 'This is the concession: language is formalizable (at least operationally).') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

INSERT INTO is_everything_a_language (is_everything_a_language_id, name, argument_name, argument_category, step_type, statement, formalization, related_candidate_name, related_candidate_id, evidence_from_rulebook, notes)
VALUES ('neial-007', 'NEIAL-007', 'NotEverythingIsALanguage', 'Premise', 'Entailment', 'If Language(x) is defined by necessary conditions, then any x that fails at least one condition is not a language.', '∀x (¬(HasSyntax(x) ∧ RequiresParsing(x) ∧ HasLinearDecodingPressure(x) ∧ StableOntologyReference(x)) → ¬Language(x))', '', '', '', 'This is the standard move: a definition implies exclusions.') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

INSERT INTO is_everything_a_language (is_everything_a_language_id, name, argument_name, argument_category, step_type, statement, formalization, related_candidate_name, related_candidate_id, evidence_from_rulebook, notes)
VALUES ('neial-008', 'NEIAL-008', 'NotEverythingIsALanguage', 'Example', 'Counterexample', 'Counterexample: a chair can be interpreted as a sign (status, design, function), but it does not constitute a language system under the operational definition.', '¬Language(Chair)', 'A Chair', '', '', 'This separates semiotic availability (can signify) from linguistic structure (has syntax/parsing/serialized meaning).') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

