INSERT INTO is_everything_a_language (is_everything_a_language_id, name, argument_name, argument_category, step_type, statement, formalization, related_candidate_name, related_candidate_id, evidence_from_rulebook, notes)
VALUES ('neial-012', 'NEIAL-012', 'NotEverythingIsALanguage', 'Observation', 'FuzzyBoundary', 'Fuzzy case: A Running App often contains embedded languages (code, UI grammars), but as an executing/interactive process it behaves like a dynamic system rather than a static serialized language artifact.', 'Borderline(A Running App): may contain ∃y Language(y) but ¬Language(A Running App) under static-serialization criteria', 'A Running App', '', '', 'This is where traditional semiotics'' ''anything is a sign'' doesn’t neatly distinguish: (1) language-as-system vs (2) meaning-making interactive processes.') ON CONFLICT (is_everything_a_language_id) DO UPDATE SET name = EXCLUDED.name, argument_name = EXCLUDED.argument_name, argument_category = EXCLUDED.argument_category, step_type = EXCLUDED.step_type, statement = EXCLUDED.statement, formalization = EXCLUDED.formalization, related_candidate_name = EXCLUDED.related_candidate_name, related_candidate_id = EXCLUDED.related_candidate_id, evidence_from_rulebook = EXCLUDED.evidence_from_rulebook, notes = EXCLUDED.notes;

